import{_ as i,C as p,o as a,c as s,a3 as A,b as l,w as E,a as r,E as B,a2 as o,j as d}from"./chunks/framework.C51MRPOx.js";const F=JSON.parse('{"title":"BERT 微调","description":"","frontmatter":{},"headers":[],"relativePath":"LLM训练/BERT微调.md","filePath":"LLM训练/BERT微调.md","lastUpdated":null}'),n={name:"LLM训练/BERT微调.md"};function D(h,t,m,u,b,C){const e=p("Mermaid");return a(),s("div",null,[t[3]||(t[3]=A('<h1 id="bert-微调" tabindex="-1">BERT 微调 <a class="header-anchor" href="#bert-微调" aria-label="Permalink to &quot;BERT 微调&quot;">​</a></h1><p>短文本要落到事先定好的几类表情。编码器加上一个分类头，用交叉熵把句子训到类别上，输出就锁在这几类里。生成式模型更重，也不容易把回答收成固定标签。</p><p>下面以中文短回复、八类表情为例：害怕、生气、疑惑、愉悦、无、悲伤、害羞、惊喜。换一套固定类别时，口径、划分和选点指标照同一套做。</p><h2 id="先把口径写死" tabindex="-1">先把口径写死 <a class="header-anchor" href="#先把口径写死" aria-label="Permalink to &quot;先把口径写死&quot;">​</a></h2><p>标注看的是说话人此刻该摆出的脸。句子里出现「伤心」「紧张」，并不自动落入对应的类。</p><table tabindex="0"><thead><tr><th>类</th><th>标</th><th>不标</th></tr></thead><tbody><tr><td>害怕</td><td>惊吓、恐惧、危险，上台或见人之前的发怵</td><td>运维式「先暂停操作」；单纯害羞时的紧张</td></tr><tr><td>生气</td><td>指责、发火、被冒犯、威胁式警告</td><td>翻白眼、阴阳怪气、懒得理</td></tr><tr><td>疑惑</td><td>没听懂、前后矛盾、真在发问</td><td>语气平静的事务询问</td></tr><tr><td>愉悦</td><td>开心、寒暄示好、满足、邀约时的高兴</td><td>惊喜的「没想到」；被夸之后的羞</td></tr><tr><td>无</td><td>通知和指引、安抚对方、出糗尴尬、嘲讽白眼</td><td>明显的喜怒哀惧</td></tr><tr><td>悲伤</td><td>失落、想念、抑郁、心疼自己</td><td>惊吓；生闷气</td></tr><tr><td>害羞</td><td>被注视、被夸、表白、初见时的羞赧</td><td>纯开心；纯害怕</td></tr><tr><td>惊喜</td><td>意外、没想到、哇居然</td><td>计划内的高兴；惊吓</td></tr></tbody></table><p>「无」内部还可以再看四种情况，用来分析错例：通知（会议室在三楼）、安抚（别想太多）、尴尬（发错群）、嘲讽（行了吧、画大饼）。这四种子型留在分析里。模型的输出维仍然是上面八类：没有尴尬脸和翻白眼可摆，安抚对方时脸保持平静。生气和嘲讽的分界是发火、威胁归生气，不耐烦、阴阳怪气归无。</p><p>几组容易混的句子写进口径，标注和补数据都按这个分：</p><ul><li>「好紧张」：上台、危险归害怕；被喜欢的人注视归害羞。</li><li>「你怎么能这样，我真的很伤心」归悲伤。</li><li>「这个功能怎么用」：平静请教归无；明显转不过弯、对不上归疑惑。</li><li>「居然 / 没想到 / 哇」：意外本身归惊喜；计划内的高兴归愉悦；惊吓归害怕；没听懂归疑惑。</li><li>离开、空、不在、群变安静归悲伤。夜里、门口这些场景词单独出现，仍按这句话在说什么标。</li></ul><p>类别顺序在三处保持一致：配置里的类别列表、标签表里的 id、数据文件里的标签字段。训练开始时核对配置和标签表，不一致就停。数据里用稳定的英文 id（<code>afraid</code>、<code>angry</code> 等），展示时再用中文名。增删类别时，配置、标签表、数据、冻结的评测集一起改。</p><h2 id="数据怎么来" tabindex="-1">数据怎么来 <a class="header-anchor" href="#数据怎么来" aria-label="Permalink to &quot;数据怎么来&quot;">​</a></h2>',11)),(a(),l(o,null,{default:E(()=>[B(e,{id:"mermaid-159",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E5%B7%B2%E6%9C%89%E8%AF%AD%E6%96%99%22%5D%20--%3E%20C%5B%22%E6%8C%89%E5%8F%A3%E5%BE%84%E6%B8%85%E6%B4%97%22%5D%0A%20%20%20%20B%5B%22%E6%B7%B7%E6%B7%86%E7%B1%BB%E7%9A%84%E5%9C%BA%E6%99%AF%E8%A1%A5%E5%8F%A5%22%5D%20--%3E%20C%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%8E%BB%E9%87%8D%E5%B9%B6%E4%B8%A2%E6%8E%89%E5%86%B2%E7%AA%81%E6%A0%87%E7%AD%BE%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E6%8E%92%E9%99%A4%E5%86%BB%E7%BB%93%E8%AF%84%E6%B5%8B%E9%9B%86%E7%9A%84%E5%8E%9F%E6%96%87%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E6%8C%89%E7%B1%BB%E5%AD%98%E6%94%BE%E7%9A%84%E8%AE%AD%E7%BB%83%E9%9B%86%22%5D%0A"})]),fallback:E(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=d("p",null,"从已有语料出发，先按口径拿掉标错的句子。典型的一批是操作指令被标成害怕：「先暂停操作」「先确认风险」说的是步骤。拿掉之后，只给仍然混淆的类补真实场景句，例如害怕、害羞、无。已经分开的类不必为了凑条数再平均加水。",-1)),t[5]||(t[5]=d("p",null,"一条样本一行：文本加类别 id。读入时丢掉空文本、未知标签、短于两个字的句子。同一句话出现两次且标签相同，留一条；两条标签互相冲突，都丢掉，避免监督自相矛盾。",-1)),t[6]||(t[6]=d("p",null,"评测用的手工句子事先冻结。合成训练集时排除这些原文，也排除用来探盲区的扩充句，避免同一句话既出现在训练里又出现在考试里。",-1)),t[7]||(t[7]=d("p",null,"划分用分层抽样，大约 8:1:1，种子固定，两次实验才能对齐。这份测试集和训练来自同一堆句子，只能看出模型有没有记住这堆分布。换数据、换参数、换骨干时，对比同一份冻结的手工集。手工集要改，单独立项，否则前后分数没法比。划分测试到了九成、手工集停在七成上下，说明训练句彼此太像，上线观感以手工集为准。",-1)),t[8]||(t[8]=d("h2",{id:"模型",tabindex:"-1"},[r("模型 "),d("a",{class:"header-anchor",href:"#模型","aria-label":'Permalink to "模型"'},"​")],-1)),(a(),l(o,null,{default:E(()=>[B(e,{id:"mermaid-175",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20T%5B%22%E7%9F%AD%E6%96%87%E6%9C%AC%22%5D%20--%3E%20K%5B%22%E5%88%86%E8%AF%8D%3Cbr%2F%3E%E8%A1%A5%E9%BD%90%E6%88%96%E6%88%AA%E6%96%AD%E5%88%B0%E5%9B%BA%E5%AE%9A%E9%95%BF%E5%BA%A6%22%5D%0A%20%20%20%20K%20--%3E%20Enc%5B%22BERT%20%E7%BC%96%E7%A0%81%E5%99%A8%3Cbr%2F%3E12%20%E5%B1%82%20%C2%B7%20%E9%9A%90%E5%B1%82%20768%22%5D%0A%20%20%20%20Enc%20--%3E%20Cls%5B%22%E5%8F%96%20CLS%22%5D%0A%20%20%20%20Cls%20--%3E%20Head%5B%22Dropout%20%E2%86%92%20Linear%20%E2%86%92%20logits%22%5D%0A"})]),fallback:E(()=>[...t[1]||(t[1]=[r(" Loading... ",-1)])]),_:1})),t[9]||(t[9]=A('<p>参数大约一亿，几乎都在编码器里。取编码器的 pooler 输出；没有 pooler 就用最后一层第一个位置。分类头是一层线性变换，权重用标准差 0.02 的正态初始化，偏置为 0。前向直接返回 logits。交叉熵打在 logits 上；softmax、取最大类、低置信时改成兜底类，都留在推理。</p><p>数据很少时可以冻住编码器，只训分类头，先确认这批句子和标签能分开。句子够了就全参微调。全参微调的学习率用 <code>2e-5</code> 这一档，比从头训练小很多，避免把预训练的中文表示冲掉。若接着一次冻住编码器的权重继续训，要把编码器解开。</p><p>隐层宽度从预训练配置读取。换骨干就要重新训练，分词和下游使用的固定长度一起换。</p><p>分数上不去时，先核对口径和训练句是不是同一套分布。层数、多头、把上一句历史拼进来，解决不了标签和场景没对齐的问题。</p><h2 id="参数各自决定什么" tabindex="-1">参数各自决定什么 <a class="header-anchor" href="#参数各自决定什么" aria-label="Permalink to &quot;参数各自决定什么&quot;">​</a></h2><p>超参、路径、阈值写在同一份配置里。对比实验只改这一份，种子保持不变。</p><table tabindex="0"><thead><tr><th>参数</th><th>这一档任务上的取值</th><th>决定什么</th></tr></thead><tbody><tr><td>学习率</td><td><code>2e-5</code></td><td>AdamW 的峰值。全参微调 BERT 常用这个量级；再大，预训练特征容易被冲掉</td></tr><tr><td>batch</td><td>16</td><td>显存不够再降。batch 一变，每个 epoch 的 step 数就变，warmup 的步数跟着变</td></tr><tr><td>epoch 上限</td><td>25</td><td>循环最多跑这么多轮。真正停靠早停，很少跑满</td></tr><tr><td>warmup 比例</td><td>0.1</td><td>总 step 的一成用来把学习率从 0 升到峰值，之后线性降到 0。每个 batch 更新一次</td></tr><tr><td>权重衰减</td><td>0.01</td><td>抑制权重过大</td></tr><tr><td>梯度裁剪</td><td>1.0</td><td>单步更新的幅度上限</td></tr><tr><td>早停耐心</td><td>3</td><td>验证 Macro F1 连续 3 个 epoch 没有超过历史最佳就停，并加载最佳权重</td></tr><tr><td>标签平滑</td><td>0.1</td><td>正确类大约留 0.9，其余类分掉 0.1。减轻「分错了仍然给出接近 1 的概率」</td></tr><tr><td>类别权重</td><td>关</td><td>打开后按训练集频数的反比加权。少类极少时有用；少类一旦被灌得很多，权重会压过其它类</td></tr><tr><td>序列长度</td><td>128</td><td>短句补齐，超长截断。单条回复通常远短于 128。下游要固定形状时，训完再改长度就要重新导出</td></tr></tbody></table><p>选模型的指标是验证集 Macro F1。类别一旦不均衡，准确率会被大类撑住，checkpoint 里可以记下准确率，比较时以 F1 为准。</p><p>推理可以设置信度阈值：最大概率低于阈值就改成兜底类「无」。阈值放在 0.35 时，不少错例的概率仍然高于 0.9，阈值碰不到它们。先把标签平滑和数据做好，再考虑把阈值抬高。</p><h2 id="一个-step-在做什么" tabindex="-1">一个 step 在做什么 <a class="header-anchor" href="#一个-step-在做什么" aria-label="Permalink to &quot;一个 step 在做什么&quot;">​</a></h2>',10)),(a(),l(o,null,{default:E(()=>[B(e,{id:"mermaid-330",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E4%B8%80%E6%89%B9%E5%8F%A5%E5%AD%90%22%5D%20--%3E%20B%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20%2B%20%E5%88%86%E7%B1%BB%E5%A4%B4%3Cbr%2F%3Elogits%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%8F%8D%E4%BC%A0%E5%B9%B6%E8%A3%81%E5%89%AA%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22AdamW%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%E6%8C%89%20step%20%E5%8D%87%E9%99%8D%22%5D%0A"})]),fallback:E(()=>[...t[2]||(t[2]=[r(" Loading... ",-1)])]),_:1})),t[10]||(t[10]=d("p",null,"训练模式下累计的准确率到后期会接近满分，它说明这批句子被拟合了。验证时关掉 Dropout、停掉梯度，留下全部预测，用来算 Macro F1 和混淆矩阵。验证 F1 超过历史最佳才覆盖最佳权重；每一轮的权重可以另存，方便回看是从哪一轮开始变差的。跑完后用最佳权重量一遍划分出来的测试集，看分类报告。这个数和冻结手工集分开读。",-1)),t[11]||(t[11]=d("p",null,"一轮迭代是：改口径或补句子，重新合成训练集并继续排除金标原文，再训练，最后在同一份冻结集上对比。",-1))])}const T=i(n,[["render",D]]);export{F as __pageData,T as default};
